          flex: 1;
          margin: 0 20px;
          display: flex;
          max-width: 400px;
        }
        input[type="search"] {
          flex: 1;
          padding: 8px 12px;
          border: 1px solid #ccc;
          border-radius: 4px 0 0 4px;
          font-size: 1rem;
          outline-offset: 2px;
        }
        button.search-btn {
          background: #007bff;
