            href="#"
            onClick={(e) => {
              e.preventDefault();
              setPage("cart");
            }}
            aria-label="Open cart"
          >
            Cart
          </a>
        </nav>
      </header>

      <main>
        {page === "home" && (
          <>
            <h2>New arrivals</h2>
            {addedMessage && <p className="message" role="alert">{addedMessage}</p>}
            <section className="products" aria-label="New arrivals products">
              {filteredProducts.map((product) => (
                <article key={product.id} className="card">
                  <img
                    src={`/runtime/photos/${product.photoKey}.jpg`}
                    alt={product.name}
                    width={280}
                    height={160}
                    loading="lazy"
                  />
                  <h3>{product.name}</h3>
                  <p className="price">${product.price}</p>
                  <button
                    onClick={() => handleAddToCart(product)}
                    aria-label={`${product.buttonText} for ${product.name}`}
                  >
                    {product.buttonText}
                  </button>
                </article>
              ))}
            </section>
          </>
        )}

        {page === "cart" && (
          <section aria-label="Shopping cart">
            <h2 className="cart-header">Cart</h2>
            {cart.length === 0 ? (
              <p className="empty-cart">Your cart is empty.</p>
            ) : (
              <ul className="cart-list">
                {cart.map((item, i) => (
                  <li key={`${item.id}-${i}`}>{item.name} - ${item.price}</li>
                ))}
              </ul>
            )}
            <button
              onClick={() => setPage("home")}
              style={{
                marginTop: "20px",
                backgroundColor: "#007bff",
                color: "white",
                border: "none",
                padding: "10px 16px",
                borderRadius: "6px",
                cursor: "pointer",
                width: "100%",
                fontSize: "1rem",
                userSelect: "none",
              }}
              aria-label="Back to home"
            >
              Back to home
            </button>
          </section>
        )}
      </main>
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

